60	  const listRoutines: Handler = async (ctx) => {
61	    const companyId = ctx.param("companyId") ?? "";
62	    assertCompanyAccess(ctx, companyId);
63	    const result = await svc.list(companyId);
64	    return Response.json(result);
65	  };
66	
67	  // server/src/routes/routines.ts:67
68	  const createRoutine: Handler = async (ctx) => {
69	    const companyId = ctx.param("companyId") ?? "";
70	    const body = await ctx.json();
71	    const parsed = createRoutineSchema.parse(body);
72	    await assertBoardCanAssignTasks(ctx, companyId);
73	    assertCanManageCompanyRoutine(ctx, companyId, parsed.assigneeAgentId);
74	    const created = await svc.create(companyId, parsed, {
75	      agentId: ctx.actor?.type === "agent" ? (ctx.actor.agentId ?? null) : null,
76	      userId: ctx.actor?.type === "board" ? (ctx.actor.userId ?? "board") : null,
77	    });
